def calc(expr: str) -> int | str:
    import sys
    sys.setrecursionlimit(max(sys.getrecursionlimit(), 100000))
    s = expr
    n = len(s)
    i = 0

    def skip() -> None:
        nonlocal i
        while i < n and s[i] == " ":
            i += 1

    def trunc_div(a: int, b: int) -> int:
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        return q

    def parse_expr():
        left = parse_term()
        if left == "error":
            return "error"
        while True:
            skip()
            if i >= n or s[i] not in "+-":
                return left
            op = s[i]
            i += 1
            right = parse_term()
            if right == "error":
                return "error"
            left = left + right if op == "+" else left - right

    def parse_term():
        left = parse_unary()
        if left == "error":
            return "error"
        while True:
            skip()
            if i >= n or s[i] not in "*/%":
                return left
            op = s[i]
            i += 1
            right = parse_unary()
            if right == "error" or (op != "*" and right == 0):
                return "error"
            if op == "*":
                left = left * right
            elif op == "/":
                left = trunc_div(left, right)
            else:
                left = left - right * trunc_div(left, right)

    def parse_unary():
        skip()
        sign = 1
        while i < n and s[i] == "-":
            sign = -sign
            i += 1
            skip()
        val = parse_power()
        if val == "error":
            return "error"
        return val if sign == 1 else -val

    def parse_power():
        base = parse_primary()
        if base == "error":
            return "error"
        skip()
        if i >= n or s[i] != "^":
            return base
        i += 1
        exp = parse_unary()
        if exp == "error" or exp < 0:
            return "error"
        return base ** exp

    def parse_primary():
        skip()
        if s[i] == "(":
            i += 1
            val = parse_expr()
            skip()
            i += 1
            return val
        start = i
        while i < n and s[i].isdigit():
            i += 1
        return int(s[start:i])

    return parse_expr()
